//
// What every operator header shares: the element types' numbers and the error buffer, generated by
// cbindgen from the operator crate's `crates/ops/src/abi.rs` (`ops::abi`): do not edit.
//
// An enumerator is its enumeration's name and its variant in capitals, the variant being the
// value's spelling in a kernel key: `bf16` is `UNISERVE_DTYPE_BF16`.
//
// `cargo test -p ops` compares this file with the generator's output, and this command writes it:
//
//   UPDATE_EXPECT=1 cargo test -p ops abi::headers

#pragma once

#include <cstddef>
#include <cstdint>

/// The bytes of a call structure's `error` field: the NUL-terminated message an entry writes
/// when it returns nonzero, the NUL included.
constexpr static const size_t UNISERVE_MESSAGE = 512;

/// An element type as a native package reads it: the number a call structure's element-type
/// fields carry, and the enumerator a build module's definitions name.
///
/// A variant's name is the element type's spelling in a kernel key ([`name`]), in capitals.
enum uniserve_dtype : int32_t {
  UNISERVE_DTYPE_U8 = 0,
  UNISERVE_DTYPE_I32 = 1,
  UNISERVE_DTYPE_I64 = 2,
  UNISERVE_DTYPE_F16 = 3,
  UNISERVE_DTYPE_BF16 = 4,
  UNISERVE_DTYPE_F32 = 5,
  UNISERVE_DTYPE_F8E4M3 = 6,
  /// NVFP4's element: two share a byte.
  UNISERVE_DTYPE_F4E2M1 = 7,
  UNISERVE_DTYPE_I16 = 8,
  UNISERVE_DTYPE_U32 = 9,
  UNISERVE_DTYPE_F64 = 10,
};
